.liquid-wrap {
  width: 100%; height: 100%; display: flex; align-items: center; justify-content: center;
  background: #111; overflow: hidden; position: relative;
}
.liquid-text {
  font-size: 60px; font-weight: 900; font-family: sans-serif;
  background: linear-gradient(90deg, #ff007f, #00d2ff, #00ffcc);
  -webkit-background-clip: text; color: transparent;
  filter: url(#liquid-filter); transition: filter 0.3s;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;background:#111;display:flex;align-items:center;justify-content:center;';

// SVG ફિલ્ટર જે પાણી જેવી ઇફેક્ટ આપે છે
c.innerHTML = `
  <svg style="position:absolute; width:0; height:0;">
    <filter id="liquid-filter">
      <feTurbulence type="fractalNoise" baseFrequency="0.02" numOctaves="3" result="noise" id="turb" />
      <feDisplacementMap in="SourceGraphic" in2="noise" scale="0" xChannelSelector="R" yChannelSelector="G" id="disp" />
    </filter>
  </svg>
  <div class="liquid-text">LIQUID METAL</div>
`;

const dispMap = document.getElementById('disp');
const turb = document.getElementById('turb');
let isHovered = false;
let waveScale = 0;
let time = 0;

c.querySelector('.liquid-text').addEventListener('pointerenter', () => isHovered = true);
c.querySelector('.liquid-text').addEventListener('pointerleave', () => isHovered = false);

function animateLiquid() {
  time += 0.05;
  turb.setAttribute('baseFrequency', `0.02 ${0.02 + Math.sin(time)*0.01}`); // સતત વહેવાનો અનુભવ

  // હોવર કરવાથી પાણીની લહેરો વધશે
  waveScale += ((isHovered ? 30 : 0) - waveScale) * 0.1;
  dispMap.setAttribute('scale', waveScale);

  requestAnimationFrame(animateLiquid);
}
animateLiquid();
